{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "PF-06455943, a morpholine-substituted pyrrolopyrimidine PET ligand, showed favorable brain uptake in rodents, supporting CNS access for a closely related morpholine/aminopyrimidine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Compound 6, a morpholine sulfonamide aminopyrimidine, achieved a brain/plasma ratio of 2.4 in rats, demonstrating that this chemotype can penetrate the BBB effectively.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Compound 4, a close analogue with a morpholine sulfonamide and chloropyrimidine, showed a B/P ratio of 3.0 in rats, further supporting high CNS exposure for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine kinase inhibitor with a basic amine, showed brain/plasma >1 in mice, indicating meaningful CNS access for a structurally related aminopyrimidine.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CLR457, a morpholine/aminopyrimidine oncology compound, had a brain/plasma AUC ratio of 0.07, indicating poor CNS penetration; however, it contains an oxazolidinone and CF3 not present in the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Compound 70 had poor CSF exposure due to very high lipophilicity and low passive permeability, liabilities not shared by the query (logD 3.93).",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest transferable evidence, including morpholine/aminopyrimidine analogues with direct brain-penetration measurements, supports meaningful CNS access. Negative analogues carry additional polar or efflux liabilities absent in the query, and the query's moderate logD, neutral charge, and low HBD are consistent with BBB penetration.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the query itself; all analogues have low Morgan similarity (<0.3).",
    "No experimental P-gp/BCRP efflux data for the query.",
    "No unbound brain concentration or target occupancy data."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

